CREATE TABLE workspace_settings(key TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)), updated REAL NOT NULL);
CREATE TABLE search_portfolios(id TEXT PRIMARY KEY, name TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), revision INTEGER NOT NULL DEFAULT 1, updated REAL NOT NULL);
CREATE TABLE opportunity_index(identity TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)), first_seen REAL NOT NULL, checked REAL NOT NULL, saved INTEGER NOT NULL DEFAULT 0 CHECK(saved IN (0,1)), opened REAL, application_id TEXT REFERENCES applications(id));
CREATE INDEX opportunities_recent ON opportunity_index(checked DESC);
CREATE TABLE application_history(application_id TEXT PRIMARY KEY REFERENCES applications(id), snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), applied REAL, outcome TEXT NOT NULL DEFAULT 'Awaiting response', notes TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE history_events(id INTEGER PRIMARY KEY AUTOINCREMENT, application_id TEXT NOT NULL REFERENCES applications(id), kind TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created REAL NOT NULL);
CREATE TRIGGER history_events_immutable_update BEFORE UPDATE ON history_events BEGIN SELECT RAISE(ABORT,'history events are append only'); END;
CREATE TRIGGER history_events_immutable_delete BEFORE DELETE ON history_events BEGIN SELECT RAISE(ABORT,'history events are append only'); END;
CREATE TABLE assessments(id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), component TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('TO_DO','IN_PROGRESS','COMPLETED_USER_REPORTED','COMPLETED_CONFIRMED','CANCELLED','NEEDS_REVIEW')), deadline TEXT NOT NULL DEFAULT '', evidence_id TEXT, revision INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL, UNIQUE(application_id,evidence_id,component));
CREATE TABLE mail_tracking(connection_id TEXT PRIMARY KEY REFERENCES mail_connections(id), enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), interval_seconds INTEGER NOT NULL DEFAULT 86400 CHECK(interval_seconds=86400), lookback_days INTEGER NOT NULL DEFAULT 90 CHECK(lookback_days BETWEEN 1 AND 365), next_due REAL NOT NULL DEFAULT 0, last_success REAL, history_id TEXT, page_token TEXT, sync_mode TEXT NOT NULL DEFAULT 'initial', anchor_history TEXT, status TEXT NOT NULL DEFAULT 'DISABLED', lease_until REAL NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0);
CREATE TABLE recruitment_messages(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES mail_connections(id), message_id TEXT NOT NULL, application_id TEXT REFERENCES applications(id), classification TEXT NOT NULL, protected_payload TEXT NOT NULL, received REAL NOT NULL, resolved INTEGER NOT NULL DEFAULT 0 CHECK(resolved IN (0,1)), UNIQUE(connection_id,message_id));
CREATE TABLE workspace_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('RUNNING','DONE','FAILED','CANCELLED')), result TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(result)), created REAL NOT NULL, updated REAL NOT NULL);
